The model is pre-baked with certain judging criteria (see the section titled Definitions for Pre-baked Criteria for the complete list). We will now see a few examples of how to use the pre-baked criteria as well as how users can specify their own criteria. We will also see how to activate thinking mode. Let us setup the imports, load the model and a utility function to parse the model outputs including reasoning traces or chain-of-thought. import json import re from vllm import LLM, SamplingParams from transformers import AutoTokenizer model_path = "ibm-granite/granite-guardian-4.1-8b" # Load tokenizer and model tokenizer = AutoTokenizer.from_pretrained(model_path) llm = LLM(model=model_path, max_model_len=8192) sampling_params = SamplingParams(temperature=0.0, max_tokens=2048) # Guardian judge instructions for think / no-think modes GUARDIAN_JUDGE_THINK = ( "<think>As a judge agent, carefully analyze whether the provided text meets the " "given judging criteria. Use all available information, including conversations, " "documents, and tools. Reason through the evidence step by step before providing " "your score. Wrap your reasoning in <think></think> tags, then provide your " "score in <score></score> tags." ) GUARDIAN_JUDGE_NOTHINK = ( "<no-think>As a judge agent, assess whether the provided text meets the given " "judging criteria using all available information, including conversations, " "documents, and tools. Provide your score immediately without explanation. " "Output empty <think>\n</think> tags followed by your score in <score></score> tags." ) def build_guardian_block(criteria, think=False): judge_instruction = GUARDIAN_JUDGE_THINK if think else GUARDIAN_JUDGE_NOTHINK return ( f"<guardian>{judge_instruction}

" f"### Criteria: {criteria}

" f"### Scoring Schema: If the last assistant's text meets the criteria, " f"return 'yes'; otherwise, return 'no'." ) def parse_output(text): text_clean = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL).strip() match = re.findall(r"<score>\s*(.*?)\s*</score>", text_clean, re.DOTALL) if match: return match[0].strip().lower() return None

The easiest way to use this model is through the 🐥Docling library. It will automatically download this model and convert documents to various formats for you. Install the latest version of docling through pip, then use the following CLI command: # Convert to HTML and Markdown: docling --to html --to md --pipeline vlm --vlm-model granite_docling "https://arxiv.org/pdf/2501.17887" # accepts files, urls or directories # Convert to HTML including layout visualization: docling --to html_split_page --show-layout --pipeline vlm --vlm-model granite_docling "https://arxiv.org/pdf/2501.17887" You can also set this model up within the Docling SDK: from docling.datamodel import vlm_model_specs from docling.datamodel.base_models import InputFormat from docling.datamodel.pipeline_options import ( VlmPipelineOptions, ) from docling.document_converter import DocumentConverter, PdfFormatOption from docling.pipeline.vlm_pipeline import VlmPipeline source = "https://arxiv.org/pdf/2501.17887" ###### USING SIMPLE DEFAULT VALUES # - GraniteDocling model # - Using the transformers framework converter = DocumentConverter( format_options={ InputFormat.PDF: PdfFormatOption( pipeline_cls=VlmPipeline, ), } ) doc = converter.convert(source=source).document print(doc.export_to_markdown()) ###### USING MACOS MPS ACCELERATOR # For more options see the compare_vlm_models.py example. pipeline_options = VlmPipelineOptions( vlm_options=vlm_model_specs.GRANITEDOCLING_MLX, ) converter = DocumentConverter( format_options={ InputFormat.PDF: PdfFormatOption( pipeline_cls=VlmPipeline, pipeline_options=pipeline_options, ), } ) doc = converter.convert(source=source).document print(doc.export_to_markdown()) Alternatively, you can use bare transformers, vLLM, onnx or mlx-vlm to perform inference, and docling-core APIs to convert results to variety of output formats (md, html, etc.). Here's an example of single-page image inference using plain transformers. # Prerequisites: # pip install torch # pip install docling_core # pip install transformers import torch from docling_core.types.doc import DoclingDocument from docling_core.types.doc.document import DocTagsDocument from transformers import AutoProcessor, AutoModelForVision2Seq from transformers.image_utils import load_image from pathlib import Path DEVICE = "cuda" if torch.cuda.is_available() else "cpu" # Load images image = load_image("https://huggingface.co/ibm-granite/granite-docling-258M/resolve/main/assets/new_arxiv.png") # Initialize processor and model processor = AutoProcessor.from_pretrained("ibm-granite/granite-docling-258M") model = AutoModelForVision2Seq.from_pretrained( "ibm-granite/granite-docling-258M", torch_dtype=torch.bfloat16, _attn_implementation="flash_attention_2" if DEVICE == "cuda" else "sdpa", ).to(DEVICE) # Create input messages messages = [ { "role": "user", "content": [ {"type": "image"}, {"type": "text", "text": "Convert this page to docling."} ] }, ] # Prepare inputs prompt = processor.apply_chat_template(messages, add_generation_prompt=True) inputs = processor(text=prompt, images=[image], return_tensors="pt") inputs = inputs.to(DEVICE) # Generate outputs generated_ids = model.generate(**inputs, max_new_tokens=8192) prompt_length = inputs.input_ids.shape[1] trimmed_generated_ids = generated_ids[:, prompt_length:] doctags = processor.batch_decode( trimmed_generated_ids, skip_special_tokens=False, )[0].lstrip() print(f"DocTags: 
{doctags}
") # Populate document doctags_doc = DocTagsDocument.from_doctags_and_image_pairs([doctags], [image]) # create a docling document doc = DoclingDocument.load_from_doctags(doctags_doc, document_name="Document") print(f"Markdown:
{doc.export_to_markdown()}
") ## export as any format. # Path("out/").mkdir(parents=True, exist_ok=True) # HTML: # output_path_html = Path("out/") / "example.html" # doc.save_as_html(output_path_html) # Markdown: # output_path_md = Path("out/") / "example.md" # doc.save_as_markdown(output_path_md) Here's an example of fast batch inference using vLLM: # Prerequisites: # pip install vllm # pip install docling_core # place page images you want to convert into "img/" dir import time import os from vllm import LLM, SamplingParams from transformers import AutoProcessor from PIL import Image from docling_core.types.doc import DoclingDocument from docling_core.types.doc.document import DocTagsDocument from pathlib import Path # Configuration MODEL_PATH = "ibm-granite/granite-docling-258M" IMAGE_DIR = "img/" # Place your page images here OUTPUT_DIR = "out/" PROMPT_TEXT = "Convert this page to docling." messages = [ { "role": "user", "content": [ {"type": "image"}, {"type": "text", "text": PROMPT_TEXT}, ], }, ] # Ensure output directory exists os.makedirs(OUTPUT_DIR, exist_ok=True) # Initialize LLM llm = LLM(model=MODEL_PATH, revision="untied", limit_mm_per_prompt={"image": 1}) processor = AutoProcessor.from_pretrained(MODEL_PATH) sampling_params = SamplingParams( temperature=0.0, max_tokens=8192, skip_special_tokens=False, ) # Load and prepare all images and prompts up front batched_inputs = [] image_names = [] for img_file in sorted(os.listdir(IMAGE_DIR)): if img_file.lower().endswith((".png", ".jpg", ".jpeg")): img_path = os.path.join(IMAGE_DIR, img_file) with Image.open(img_path) as im: image = im.convert("RGB") prompt = processor.apply_chat_template(messages, add_generation_prompt=True) batched_inputs.append({"prompt": prompt, "multi_modal_data": {"image": image}}) image_names.append(os.path.splitext(img_file)[0]) # Run batch inference start_time = time.time() outputs = llm.generate(batched_inputs, sampling_params=sampling_params) # Postprocess all results for img_fn, output, input_data in zip(image_names, outputs, batched_inputs): doctags = output.outputs[0].text output_path_dt = Path(OUTPUT_DIR) / f"{img_fn}.dt" output_path_md = Path(OUTPUT_DIR) / f"{img_fn}.md" with open(output_path_dt, "w", encoding="utf-8") as f: f.write(doctags) # Convert to DoclingDocument and save markdown doctags_doc = DocTagsDocument.from_doctags_and_image_pairs([doctags], [input_data["multi_modal_data"]["image"]]) doc = DoclingDocument.load_from_doctags(doctags_doc, document_name="Document") doc.save_as_markdown(output_path_md) print(f"Total time: {time.time() - start_time:.2f} sec")

Granite Vision 4.1 is supported natively in vLLM as of commit d249a9e. Until an official release ships, install vLLM from source: git clone https://github.com/vllm-project/vllm.git cd vllm pip install -e ".[cuda]" Serving with native LoRA​ The model ships as a LoRA adapter on top of Granite 4.1 Micro. vLLM applies the adapter automatically for image requests while text-only requests use the base model: vllm serve ibm-granite/granite-vision-4.1-4b \ --enable-lora \ --max-lora-rank 256 \ --default-mm-loras '{"image": "ibm-granite/granite-vision-4.1-4b"}' \ --host 0.0.0.0 --port 8000 Client example​ Query the running server using the OpenAI-compatible API: import base64 from openai import OpenAI from huggingface_hub import hf_hub_download from PIL import Image model_id = "ibm-granite/granite-vision-4.1-4b" client = OpenAI(base_url="http://localhost:8000/v1", api_key="EMPTY") def run_inference(client, model_id, image_path, tag): with open(image_path, "rb") as f: image_b64 = base64.b64encode(f.read()).decode("utf-8") messages = [ {"role": "user", "content": [ {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{image_b64}"}}, {"type": "text", "text": tag}, ]} ] response = client.chat.completions.create( model=model_id, messages=messages, max_tokens=4096, temperature=0, ) return response.choices[0].message.content chart_path = hf_hub_download(repo_id=model_id, filename="chart.jpg") table_path = hf_hub_download(repo_id=model_id, filename="table.png") # Chart tasks for tag in ["<chart2csv>", "<chart2summary>", "<chart2code>"]: result = run_inference(client, model_id, chart_path, tag) print(f"{tag}:
{result}
") # Table tasks for tag in ["<tables_json>", "<tables_html>", "<tables_otsl>"]: result = run_inference(client, model_id, table_path, tag) print(f"{tag}:
{result}
")
